Lemma bytes_at_sub : forall m P bs (a n : nat), bytes_at usegs m P bs -> (a + n <= length bs)%nat ->
  bytes_at usegs m (P + Z.of_nat a) (firstn n (skipn a bs)).
Proof.
  intros m P bs a n WIN H.
  rewrite <- (firstn_skipn a bs) in WIN. apply bytes_at_app in WIN. destruct WIN as [_ W2].
  rewrite firstn_length_le in W2 by lia.
  rewrite <- (firstn_skipn n (skipn a bs)) in W2. apply bytes_at_app in W2. destruct W2 as [W2 _]. exact W2.
Qed.

Lemma zbytes_firstn : forall n bs, zbytes (firstn n bs) = firstn n (zbytes bs).
Proof. intros n bs. unfold zbytes. rewrite firstn_map. reflexivity. Qed.

Section HCW.
  Context {HCEIL : HeapCeil}.


Local Ltac list_eq_lia := repeat first [ reflexivity | lia | progress f_equal ].
Local Ltac close_cells OBJ :=
  first [ exact OBJ
        | lazymatch goal with |- rw_cells _ _ _ ?cs2 =>
            lazymatch type of OBJ with rw_cells _ _ _ ?cs1 =>
              replace cs2 with cs1; [exact OBJ | unfold wz, b8; list_eq_lia ] end end ].
Local Ltac nrmw := nrm; unfold wz.

Local Ltac win_loadH WIN q :=
  lazymatch type of WIN with bytes_at _ ?mx ?it0 ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q WIN ltac:(lia)) as [b N];
