(* [comment removed for export] *)
Definition fi_ctx (m m1 : mem) (sp s6v s5v s4v s3v s2v s1v s0v rav : word) (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell)
    (lo : Z) (junkR : list byte) (itc : list cell) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -64) [C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells usegs m1 R [CB 40 junkR]
  /\ rw_cells usegs m1 IT itc
  /\ rw_cells usegs m1 EA (TokItCells 0 0 (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)) (SP + Z.of_nat (length sbs)))
  /\ rw_cells usegs m1 T (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)
  /\ bytes_at usegs m1 SP sbs /\ bytes_at usegs m1 TP tbs
  /\ stk usegs m1 lo (bv_unsigned sp + -64)
  /\ munch [(lo, bv_unsigned sp); (R, R + SZ_TOKIT); (IT, IT + SZ_TOKIT)]%Z m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

Definition fi_pure (sp : word) (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo hi : Z) : Prop :=
  SP + Z.of_nat (length sbs) < 2^64 /\ TP + Z.of_nat (length tbs) < 2^64
  /\ lo + FINDIF_STACK <= bv_unsigned sp /\ 0xb8000 <= lo
  /\ bv_unsigned sp <= EA /\ EA + SZ_TOKIT <= IT /\ IT + SZ_TOKIT <= R /\ R + SZ_TOKIT <= hi
  /\ (hi <= T \/ T + Z.of_nat (cells_size (C8 (wz TP) :: C8 (wz (Z.of_nat (length tbs))) :: trest)) <= lo)
  /\ (hi <= SP \/ SP + Z.of_nat (length sbs) <= lo) /\ (hi <= TP \/ TP + Z.of_nat (length tbs) <= lo)
  /\ ((0 < length sbs)%nat -> 0 < SP) /\ ((0 < length tbs)%nat -> 0 < TP)
  /\ IT mod 8 = 0 /\ EA mod 8 = 0.

Local Ltac open_fctx CTX PURE :=
  lazymatch type of CTX with fi_ctx _ _ ?sp _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ =>
  destruct CTX as (FR & RJ & ITC & EAC & TC & WS & WT & ST & MU & WM & MI);
  destruct PURE as (SP64 & TP64 & LO & L98 & LEA & LIT & LR & LHI & ST_ & SS & STP & NZS & NZT & ITAL & EAAL);
  pose proof (bytes_at_bound _ _ _ _ WS) as WSB; pose proof (bytes_at_bound _ _ _ _ WT) as WTB;
  pose proof (rw_cells_bound _ _ _ _ TC) as TCB; cbn [cells_size csize Nat.add length] in TCB, ST_;
  pose proof (rw_cells_bound _ _ _ _ RJ) as RB; cbn [cells_size csize Nat.add length] in RB;
  pose proof (rw_cells_bound _ _ _ _ EAC) as EAB; cbn [cells_size csize Nat.add length TokItCells] in EAB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold TokItCells, SZ_TOKIT, FINDIF_STACK in * end.

Local Ltac rebuild_fctx m sp R IT EA T SP TP :=
  try match goal with C : fi_ctx _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ |- _ => clear C end;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
  lazymatch goal with
  | FR : rw_cells _ mx (bv_unsigned sp + -64) [C8 ?s6v; C8 ?s5v; C8 ?s4v; C8 ?s3v; C8 ?s2v; C8 ?s1v; C8 ?s0v; C8 ?rav],
    RJ : rw_cells _ mx R [CB 40 ?junkR], ITC : rw_cells _ mx IT ?itc, EAC : rw_cells _ mx EA _,
