(* [comment removed for export] *)

Definition fi_cont (Q : machine_state -> Prop) (pc : Z) rax spx gp tp t0 t1 t2 s0 s1 s2 s3 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) : Prop :=
  forall a0' a1' a2' a3' a4' a5' a6' a7',
    evt usegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 (wz 1) (wz 2) (Z_to_bv 64 (-1)) s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (Z_to_bv 64 pc) fc None m1 (seg_rom usegs)).
Scheme kc__4 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

Lemma fi_slow : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (TP VP : Z) (tbs vbs : list byte),
  (length tbs - j = k)%nat -> (j < length tbs)%nat -> length vbs = length tbs ->
  bytes_at usegs m1 TP tbs -> bytes_at usegs m1 VP vbs -> TP + Z.of_nat (length tbs) < 2^64 -> VP + Z.of_nat (length vbs) < 2^64 ->
  mem_inv usegs m1 ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = true ->
     fi_cont Q 0x36c64 rax spx gp tp t0 t1 t2 s0 s1 s2 s3 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1) ->
  (tl_ieqb (skipn j (zbytes tbs)) (skipn j (zbytes vbs)) = false ->
     fi_cont Q 0x36c58 rax spx gp tp t0 t1 t2 s0 s1 s2 s3 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m1) ->
  evt usegs Q (MS (mkR rax spx gp tp t0 t1 t2 s0 s1 (wz (Z.of_nat (length tbs) - Z.of_nat j)) (wz (TP + Z.of_nat j)) (wz (VP + Z.of_nat j))
                       a3 a4 a5 a6 a7 s2 s3 (wz 1) (wz 2) (Z_to_bv 64 (-1)) s7 s8 s9 s10 s11 t3 t4 t5 t6)
