(* [comment removed for export] *)

Definition fi_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists vp vl itv fv,
    fi_post_r vp vl itv fv ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest lo m ms'
    /\ 0 <= itv < 2^64 /\ 0 <= fv < 2^64
    /\ v = negb ((itv =? SP + Z.of_nat (length sbs)) && (fv =? SP + Z.of_nat (length sbs))).

Lemma fi_post_v_findif : forall ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest r i lo m ms,
  fi_post_v (findif_found (zbytes tbs) r i (zbytes sbs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest lo m ms ->
  findif_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest r i lo m ms.
Proof.
  intros until ms. intros (vp & vl & itv & fv & PO & HI & HF & FF).
  eapply findif_post_of_r; [exact PO | exact HI | exact HF | exact FF].
Qed.

Lemma fi_done_v : forall (v : bool) (vp vl itv fv : Z) rax a0x a1x a2x a3x a4x a5x a6x a7x s2x s3x s4x s5x s6x ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo hi : Z) (junkR : list byte),
  fi_ctx m m1 sp s6 s5 s4 s3 s2 s1 s0 ra R IT EA T SP TP sbs tbs trest lo junkR (TokItCells vp vl itv fv (SP + Z.of_nat (length sbs))) ->
  fi_pure sp R IT EA T SP TP sbs tbs trest lo hi ->
  0 <= itv < 2^64 -> 0 <= fv < 2^64 -> v = negb ((itv =? SP + Z.of_nat (length sbs)) && (fv =? SP + Z.of_nat (length sbs))) ->
  evt usegs (fi_post_v v ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc R IT EA T SP TP sbs tbs trest lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz IT) (wz R) a0x a1x a2x a3x a4x a5x a6x a7x
              s2x s3x s4x s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x36c64) fc None m1 (seg_rom usegs)).
Proof.
  intros until junkR. intros CTX PURE HI HF HV.
  eapply evt_mono; [eapply fi_done; [exact CTX | exact PURE] |].
  intros ms' PO. exists vp, vl, itv, fv. split; [exact PO | split; [exact HI | split; [exact HF | exact HV]]].
Qed.

