Local Ltac call_incr A vp vl it fst La W wbs lo :=
  let S := fresh "IS" in
  pose proof tokit_incr_spec as S;
  unfold tokit_incr_stmt, tokit_incr_post, SZ_TOKIT, TOKIT_STACK, P_TOKEN_LIST_ITER_INCR in S;
  callZ (S A vp vl it fst La W wbs lo);
  [ fast_assumption | fast_assumption | lia | lia | lia | lia | lia
  | rewrite ?unsigned_lit by lia; fast_assumption | rewrite ?unsigned_lit by lia; lia | lia
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; lia
  | fast_assumption | fast_assumption | clear S ].

Lemma tok_suffix_off' : forall SP i sbs, 0 <= SP -> tok_suffix SP (SP + Z.of_nat i) sbs = skipn i (zbytes sbs).
Proof. intros SP i sbs H. unfold tok_suffix. rewrite zbytes_skipn. f_equal. lia. Qed.
Scheme kc__5 := Elimination for OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XP_tok_stmt.tokres Sort Prop.

Lemma fi_loop : forall (mu i : nat) (r : tokres) rax a0 a1 a2 a3 a4 a5 a6 a7 ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (R IT EA T SP TP : Z) (sbs tbs : list byte) (trest : list cell) (lo hi : Z) (junkR : list byte),
  (length sbs - i < mu)%nat -> (i <= length sbs)%nat ->
  (forall k l, r = TK_tok k l -> (i + k + l <= length sbs)%nat /\ (1 <= l)%nat) ->
  fi_ctx m m1 sp s6 s5 s4 s3 s2 s1 s0 ra R IT EA T SP TP sbs tbs trest lo junkR
         (tokit_cells_after r (SP + Z.of_nat i) (SP + Z.of_nat (length sbs))) ->
  fi_pure sp R IT EA T SP TP sbs tbs trest lo hi ->
  evt usegs (fi_post_v (findif_found (zbytes tbs) r i (zbytes sbs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc
               R IT EA T SP TP sbs tbs trest lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz IT) (wz R) a0 a1 a2 a3 a4 a5 a6 a7
              (wz T) (wz EA) (wz 1) (wz 2) (Z_to_bv 64 (-1)) s7 s8 s9 s10 s11 t3 t4 t5 t6)
