(* [comment removed for export] *)
(* [comment removed for export] *)



Local Ltac call_ctor A Fi La W wbs cs lo :=
  let S := fresh "CS" in
  pose proof tokit_ctor_spec as S;
  unfold tokit_ctor_stmt, tokit_ctor_post, SZ_TOKIT, TOKIT_STACK, P_TOKEN_LIST_ITER_CTOR in S;
  callZ (S A Fi La W wbs cs lo);
  [ fast_assumption | first [reflexivity | fast_assumption] | fast_assumption | lia | lia | lia | lia
  | rewrite ?unsigned_lit by lia; fast_assumption | rewrite ?unsigned_lit by lia; lia | lia
  | rewrite ?unsigned_lit by lia; lia | rewrite ?unsigned_lit by lia; lia
  | fast_assumption | fast_assumption | clear S ].

(* [comment removed for export] *)
Local Ltac end_checks K :=
  zstep; try (rewrite (Z.add_comm (Z.of_nat (length _)) _));
  notrap; K; zstep; zstep; zstep; rewrite nullbase_xor by lia; notrap.

(* [comment removed for export] *)
Local Ltac ex_epilogue J0 EB EAC ITC RR FRhi ST sp :=
  step; step; step;
  join_frame RR FRhi (bv_unsigned sp + -64);
  join_frame ITC RR (bv_unsigned sp + -104);
  join_frame EAC ITC (bv_unsigned sp + -144);
  join_frame EB EAC (bv_unsigned sp + -184);
  join_frame J0 EB (bv_unsigned sp + -192);
  step; release_frame J0 ST (bv_unsigned sp); step.

(* [comment removed for export] *)
Local Ltac ex_name_after sp off N SP lo :=
  lazymatch goal with H : rw_cells _ _ (bv_unsigned sp + off) _ |- _ => rename H into N end;
  try match goal with H : bytes_at _ _ SP _, H' : bytes_at _ _ SP _ |- _ => clear H' end;
  lazymatch goal with H : bytes_at _ _ SP _ |- _ => try rename H into WS end;
  lazymatch goal with H : stk _ _ lo _ |- _ => try rename H into ST end.

